import { test, expect } from '@playwright/test';

test.describe('API Response Caching', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
  });

  test('should cache API response on first visit', async ({ page }) => {
    const response = await page.request.get('/api/data');
    expect(response.ok()).toBeTruthy();

    const cachedResponse = await page.request.get('/api/data');
    expect(cachedResponse.ok()).toBeTruthy();
    expect(cachedResponse.headers()['x-cache']).toBe('HIT');
  });

  test('should return instant response on repeat visits', async ({ page }) => {
    const firstResponse = await page.request.get('/api/data');
    expect(firstResponse.ok()).toBeTruthy();

    const secondResponse = await page.request.get('/api/data');
    expect(secondResponse.ok()).toBeTruthy();
    expect(secondResponse.headers()['x-cache']).toBe('HIT');

    const firstData = await firstResponse.json();
    const secondData = await secondResponse.json();
    expect(firstData).toEqual(secondData);
  });
});
